/** 
 * Timestamps are technically time zone agnostic, and this method sort of cheats its logic. Timestamps are supposed to represent nanos since [UTC epoch]. Here, the input timestamp represents nanoseconds since [epoch at fromZone], and we return a Timestamp representing nanoseconds since [epoch at toZone].
 */
public static Timestamp convertTimestampToZone(Timestamp ts,ZoneId fromZone,ZoneId toZone,boolean legacyConversion){
  if (legacyConversion) {
    try {
      DateFormat formatter=getLegacyDateFormatter();
      formatter.setTimeZone(TimeZone.getTimeZone(fromZone));
      java.util.Date date=formatter.parse(ts.format(TIMESTAMP_FORMATTER));
      formatter.setTimeZone(TimeZone.getTimeZone(toZone));
      Timestamp result=Timestamp.valueOf(formatter.format(date));
      result.setNanos(ts.getNanos());
      return result;
    }
 catch (    ParseException e) {
      throw new RuntimeException(e);
    }
  }
  Instant instant=convert(ts,fromZone).getZonedDateTime().toInstant();
  LocalDateTime localDateTimeAtToZone=LocalDateTime.ofInstant(instant,toZone);
  return Timestamp.ofEpochSecond(localDateTimeAtToZone.toEpochSecond(ZoneOffset.UTC),localDateTimeAtToZone.getNano());
}
